def backfill_reservation_clients(apps, schema_editor):
    """Link bookings made before clients existed.

    A booking made from a lead already knows its person; a walk-in gets a
    client created from the phone at the desk. This runs after the leads
    migration, so that one has already built the client rows.
    """
    Reservation = apps.get_model("trips", "Reservation")
    Client = apps.get_model("leads", "Client")

    for reservation in Reservation.objects.select_related("lead").iterator():
        client_id = reservation.lead.client_id if reservation.lead_id else None
        if client_id is None:
            client, _created = Client.objects.get_or_create(
                agency_id=reservation.agency_id,
                phone_e164=reservation.phone_e164,
                defaults={"full_name": (reservation.full_name or "").strip()},
            )
            client_id = client.pk
        Reservation.objects.filter(pk=reservation.pk).update(client_id=client_id)


